files.concepts.memql:
/// A loop scenario row.
concept unused {
  status string
  n int
}

scenarios.automations:
/// Exercise a causal loop.
@trigger(event="loop.scenario.tick")
automation loopPublishTick {
  args {
    id any
    status any
    n any
  }
  publish "loop.scenario.tick" { id: args.id, n: args.n + 1, status: args.n >= 1 ? "done" : "open" }
}

/// Exercise a causal loop.
@trigger(event="loop.scenario.tick")
@filter(row => row.status != "done")
@loop(maxDepth=4, until=row => row.status == "done")
automation loopPublishTick {
  args {
    id any
    status any
    n any
  }
  publish "loop.scenario.tick" { id: args.id, n: args.n + 1, status: args.n >= 1 ? "done" : "open" }
}

/// Exercise a causal loop.
@trigger(event="loop.scenario.tick")
automation loopPublishTick {
  args {
    id any
    status any
    n any
  }
  builtin loopScenarioOpaquePublish(id: args.id, n: args.n + 1, status: "open")
}
